using System;using System.Data;using System.Web.UI;
namespace Training.Trainee{public partial class Notifications:System.Web.UI.Page{clsDataAccess obj=new clsDataAccess();protected void Page_Load(object s,EventArgs e){if(Session["Role"]==null||Session["Role"].ToString()!="Emp")Response.Redirect("~/Default.aspx");if(!IsPostBack)BindGrid();}private void BindGrid(){DataTable d=obj.GetDataTable("SELECT NotificationID,Message,CreatedOn FROM Notification WHERE TrainerID='ALL' OR TrainerID LIKE 'MANAGER:%' ORDER BY CreatedOn DESC");d.Columns.Add("HasPdf",typeof(bool));foreach(DataRow r in d.Rows)r["HasPdf"]=System.IO.File.Exists(Server.MapPath("~/Uploads/Notifications/"+r["NotificationID"]+".pdf"));gvNotifications.DataSource=d;gvNotifications.DataBind();}}}